<script setup>
import {ref,onMounted} from 'vue'
import Icon from './Icon.vue'
import {dateLabel,sceneName,modeLabel,signed} from '../dataModel.js'
import {statisticsSelection} from '../../utils/statisticsCatalog.js'
const props=defineProps({record:Object,source:String})
const emit=defineEmits(['close','player'])
const dialog=ref(null),copied=ref(false),copyError=ref(false)
onMounted(()=>dialog.value.showModal())
async function copy(){try{await navigator.clipboard.writeText(props.record.game_id);copied.value=true}catch{copyError.value=true}}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(props.record,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=props.record.game_id+'-摘要.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const replayUrl=(kind)=>kind==='2d'?(props.record.url_2d||'/2d/record/'+encodeURIComponent(props.record.game_id)):(props.record.url_3d||'/game-unity?recordId='+encodeURIComponent(props.record.game_id))
</script>
<template><dialog ref="dialog" class="detail-dialog" @close="emit('close')" @click="e=>{if(e.target===dialog)dialog.close()}"><div class="dialog-heading"><div><span class="eyebrow">RECORD / 对局详情</span><h2>{{record.description||'牌谱摘要'}}</h2></div><button autofocus class="icon-button" aria-label="关闭牌谱详情" @click="dialog.close()"><Icon name="close"/></button></div><div class="dialog-body"><div class="detail-id"><strong class="mono">{{record.game_id}}</strong><button class="text-button" @click="copy"><Icon :name="copied?'check':'copy'" :size="15"/>{{copied?'已复制':'复制编号'}}</button></div><span v-if="copyError" role="status">复制不可用，请选择上方编号复制。</span><dl class="record-meta"><div><dt>时间</dt><dd>{{dateLabel(record.created_at_game||record.created_at)}}</dd></div><div><dt>场次</dt><dd>{{sceneName(record)}}</dd></div><div><dt>模式</dt><dd>{{modeLabel(record.match_type,record.rule)}}</dd></div><div><dt>规则</dt><dd>{{statisticsSelection(record.sub_rule||record.rule)?.stats_name||record.rule}}</dd></div></dl><h3>对局结算</h3><div class="result-players"><div v-for="(p,i) in record.players" :key="p.user_id||i"><span class="player-seat">{{p.rank?p.rank+' 位':'—'}}</span><button class="text-button" @click="emit('player',p.user_id||p.username)">{{p.username||p.user_id}}</button><strong :class="{'score-positive':p.score>0}">{{signed(p.score)}}</strong></div></div><p class="panel-footnote">顺位为本场结算结果。得分单位与规则一致，未提供的数值不作推算。</p><div class="detail-actions" v-if="source!=='demo'"><a v-if="record.rule?.split('/')[0]==='guobiao'" class="primary-button" :href="replayUrl('2d')" target="_blank" rel="noopener">2D 回放 <Icon name="external" :size="15"/></a><a class="secondary-button" :href="replayUrl('3d')" target="_blank" rel="noopener">3D 回放 <Icon name="external" :size="15"/></a></div><p v-else class="notice">这是一条虚构示例牌谱，不提供真实回放。</p><button class="download-summary" @click="download"><Icon name="download" :size="17"/>下载这场对局的摘要 JSON</button><p class="subtle">摘要含此处可见信息；完整牌谱请在已有分析页面登录后获取。</p></div></dialog></template>
